import{esc,button as b,number as n,input,range,select}from'./ui.js';
import{balanceValues,PROOF}from'./b05-model.js';
const proofNames={paired:'任意偶数都能组成完整的对',join:'把两组完整的对放到一起',none:'没有任何一颗落单',even:'所以合起来仍是偶数'};
const dots=(n,c='#688f88')=>`<span class="x-dots" style="color:${c}">${'● '.repeat(Math.max(0,Math.min(60,n)))}</span>`;
const beam=(l,r,release)=>{const tilt=release?Math.max(-22,Math.min(22,(l-r)*3)):0;return `<svg viewBox="0 0 600 205" class="x-chart" aria-label="天平：左 ${l}，右 ${r}${release?l===r?'，平衡':'，不平衡':'，支架未松开'}"><path d="M300 70v110M265 180h70" stroke="#929a86" stroke-width="8"/><path d="M100 ${70+tilt}L500 ${70-tilt}" stroke="#687961" stroke-width="7"/>${[[100,70+tilt,l],[500,70-tilt,r]].map(([x,y,v])=>`<path d="M${x} ${y}v50m-65 0h130" stroke="#b28150" stroke-width="4"/><text x="${x}" y="${y+85}" text-anchor="middle" font-size="24">${v}</text>`).join('')}</svg>`;};
export function visual(t,m){switch(t.type){
case'x-repeat':return `<p class="x-pattern-source">${esc(t.source)}</p><p>圈出从开头起的 ${m.length} 个为一组</p><div class="x-pattern-unit">${t.source.split(' ').slice(0,m.length).map(esc).join(' ')}</div><p>我拼的单元：<b>${m.unit.map(esc).join(' ')||'还没拼'}</b></p><div class="x-pattern-chain">${m.chain.map(x=>'<span>'+esc(x)+'</span>').join('')}</div>`;
case'x-commute':{const a=m.swapped?t.b:t.a,c=m.swapped?t.a:t.b;return `<div class="x-bowls"><div>${dots(a)}<p>${a}</p></div><b>＋</b><div>${dots(c,'#b28150')}<p>${c}</p></div></div>`;}
case'x-placevalue':return `<p>十颗一束</p><div class="x-tens">${Array.from({length:4+m.added},()=>'<span>十</span>').join('')}</div><p>散开的珠子</p>${dots(7)}`;
case'x-shapefacts':{const w=m.shape?180:m.width*45,h=m.shape?180:m.height*45,x=300-w/2,y=150-h/2,points=[[x,y],[x+w,y],[x+w,y+h],[x,y+h]],marks=m.marks[m.shape];return `<svg viewBox="0 0 600 310" class="x-chart" aria-label="${m.shape?'正方形':'长方形'}，点击标记边或直角"><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#e5eee3"/>${points.map(([a,c],i)=>{const [e,f]=points[(i+1)%4];return `<path d="M${a} ${c}L${e} ${f}" stroke="${marks.sides.includes(i)?'#b28150':'#a8b6a2'}" stroke-width="${m.kind==='sides'?12:4}" />${m.kind==='sides'?`<rect x="${Math.min(a,e)-6}" y="${Math.min(c,f)-6}" width="${Math.max(12,Math.abs(a-e)+12)}" height="${Math.max(12,Math.abs(c-f)+12)}" fill="transparent" data-x="shape-mark" data-index="${i}" tabindex="0" role="button" aria-label="边 ${i+1}"/>`:''}<circle cx="${a}" cy="${c}" r="12" fill="${marks.corners.includes(i)?'#8e84aa':'#fff'}" stroke="#777" ${m.kind==='corners'?`data-x="shape-mark" data-index="${i}" tabindex="0" role="button" aria-label="直角 ${i+1}"`:''}/>`;}).join('')}</svg>`;}
case'x-grow':return `<div class="x-towers">${m.heights.map((h,i)=>`<div><span>${h}</span><div style="height:${h*3}px;background:${i<(t.known||0)?'#a3b79c':'#b28150'}"></div><small>第 ${i+1} ${t.towers?'座':'项'}</small></div>`).join('')}</div>`;
case'x-balance':return `<p class="x-equation">${t.left}　?　${t.right}</p>${beam(m.left,m.right,m.released)}<div class="x-bowls"><div>${dots(m.left)}</div><div>${dots(m.right,'#b28150')}</div></div>`;
case'x-unknown':{const[l,r]=balanceValues(t,m);return `<p class="x-equation">${esc(t.label)}</p><p>盒中 ${m.box} 颗${t.mode==='subtract'?'，拿走 3 颗后还剩 '+(m.box-3)+' 颗':''}</p>${beam(l,r,true)}${m.checked?`<p>代回：${t.label.replace('□',String(m.box))} · ${l===r?'两边相同':'两边还不相同'}</p>`:''}`;}
case'x-story':return `<p class="x-question-preview">${esc(t.story)}</p><p>两部分</p><div class="x-strip" style="grid-template-columns:${Math.max(1,m.a)}fr ${Math.max(1,m.b)}fr"><span style="background:#688f88;color:white;text-align:center;line-height:48px">${m.a}</span><span style="background:#b28150;color:white;text-align:center;line-height:48px">${m.b}</span></div><p>这两部分合起来 ${m.a+m.b}</p>`;
case'x-reason':return t.mode==='line'?`<svg viewBox="0 0 600 170" class="x-chart"><path d="M40 85H560" stroke="#9ba68e" stroke-width="3"/>${Array.from({length:6},(_,i)=>`<text x="${40+i*104}" y="120" text-anchor="middle">${8+i}</text><path d="M${40+i*104} 75v20" stroke="#8b9981"/>`).join('')}<circle cx="${40+m.jumps*104}" cy="85" r="10" fill="#b28150"/>${Array.from({length:m.jumps},(_,i)=>`<path d="M${40+i*104} 70q52 -60 104 0" fill="none" stroke="#b28150" stroke-width="3"/>`).join('')}</svg>`:`${t.mode==='repair'?'<p class="x-question-preview">待修正：8 + 5 → 8 + 2 + 5 → 15</p>':''}<p>原来的八颗，加上从五颗中拿出的 ${m.split} 颗</p>${dots(8)}${dots(m.split,'#b28150')}<p>五颗中还留着 ${5-m.split} 颗</p>${dots(5-m.split,'#b28150')}`;
case'x-regroup':return `<table class="x-column" aria-label="27 加 18 的竖式"><tr><td></td><td>${m.swaps?'¹':''}</td><td></td></tr><tr><td></td><td>2</td><td>7</td></tr><tr><td>＋</td><td>1</td><td>8</td></tr><tr class="sum"><td></td><td>${m.swaps?'4':'?'}</td><td>${m.swaps?'5':'?'}</td></tr></table>`+`${t.error?'<p class="x-question-preview">错误做法：27 + 18 → 三个十、十五个一 → 315</p>':''}${!m.joined?`<div class="x-bowls"><div><p>27</p>十 十${dots(7)}</div><div><p>18</p>十${dots(8,'#b28150')}</div></div>`:`<div class="x-tens">${Array.from({length:m.tens},()=>'<span>十</span>').join('')}</div>${dots(m.ones)}<p>${m.tens} 个十与 ${m.ones} 个一</p>`}`;
case'x-proof':return `<div class="x-bowls"><div>${Array.from({length:m.a},()=>'<span class="x-pair">●●</span>').join('')}</div><div>${Array.from({length:m.b},()=>'<span class="x-pair">●●</span>').join('')}</div></div><p>合起来仍是一对对的：${Array.from({length:m.a+m.b},()=>'<span class="x-pair">●●</span>').join('')}</p><p>试过的例子：${m.examples.map(([a,c])=>2*a+' + '+2*c+' = '+2*(a+c)).join('；')||'还未记录'}</p><p>我的理由：${m.chain.map(k=>proofNames[k]).join(' → ')||'先把理由拼起来'}</p>${m.counterBuilt?`<p>反例：${m.counterA} + ${m.counterB} = ${m.counterA+m.counterB}</p>${Array.from({length:Math.floor((m.counterA+m.counterB)/2)},()=>'<span class="x-pair">●●</span>').join('')}${(m.counterA+m.counterB)%2?'<span class="x-single">● 落单了</span>':''}`:''}`;
default:return'';}}
export function controls(t,m){switch(t.type){
case'x-repeat':return `${range('length','重复单元有几个位置',m.length,1,8)}<div class="choice-line">${t.palette.map(v=>b('unit-token',v,`data-value="${v}"`)).join('')}${b('unit-undo','拿走最后一个')}</div><div class="choice-line">${b('repeat-unit','接上一个我的单元')}${b('clear-chain','清空长链')}</div>`;
case'x-commute':return `${b('swap-piles','交换两堆')}<div class="x-fields">${n('a','交换后前一堆',m.a)}${n('b','交换后后一堆',m.b)}${n('total','合起来',m.total)}</div>`;
case'x-placevalue':return `<div class="choice-line">${b('add-ten','加一束十颗','data-delta="1"')}${b('add-ten','拿走一束','data-delta="-1"')}</div><div class="x-fields">${n('tens','现在几个十',m.tens)}${n('ones','现在几个一',m.ones)}${n('total','现在总共',m.total)}</div>`;
case'x-shapefacts':return `<div class="choice-line">${b('shape-select','长方形','data-index="0"')}${b('shape-select','正方形','data-index="1"')}${b('shape-kind','描边','data-value="sides"')}${b('shape-kind','标直角','data-value="corners"')}</div>${m.shape===0?`<div class="x-fields">${range('width','拉宽',m.width,2,6)}${range('height','拉高',m.height,2,6)}</div>`:''}<div class="x-fields">${n('sides','两种图形都各有几条边',m.sides)}${n('corners','都各有几个直角',m.corners)}${select('extra','正方形还要满足',m.extra,[['same-length','四边一样长'],['two','只有两个直角'],['long','一边必须更长']])}</div>`;
case'x-grow':return `<div class="x-fields">${n('start','从几开始',m.start)}${input('step','每次改变多少（减少用负号）',m.step)}${t.towers?n('prediction','先猜第六座有几块',m.prediction,m.committed!==null?'disabled':''):''}</div><div class="x-fields">${m.heights.map((v,i)=>(t.given?t.given.includes(i):i<t.known)?'':range('heights.'+i,'第 '+(i+1)+(t.towers?' 座':' 项'),v,0,60,1,!!t.towers&&m.prediction===null)).join('')}</div>`;
case'x-balance':return `<div class="choice-line">${['left','right'].map((side,i)=>b('balance-add',(i?'右':'左')+'盘加一颗',`data-side="${side}" data-delta="1"`)+b('balance-add','拿走一颗',`data-side="${side}" data-delta="-1"`)).join('')}</div>${select('guess','先猜天平会怎样',m.guess,[['level','两边一样高'],['left','左边更重'],['right','右边更重']])}${b('balance-release','留下预测，松开支架')}${select('symbol','两边应该用什么符号',m.symbol,[['equal','= 一样多'],['different','≠ 不一样多']])}`;
case'x-unknown':return `${range('box','空盒里放几颗',m.box,t.mode==='subtract'?3:0,20)}${n('written','方框应该填',m.written)}${b('unknown-check','放回原式检查')}`;
case'x-story':return `<div class="x-fields">${range('a','第一部分',m.a,0,20)}${range('b','第二部分',m.b,0,20)}${n('total','整体有多少',m.total)}${select('whole','故事里的整体是谁',m.whole,[['total','所有贴纸／苹果'],['first','第一部分'],['second','第二部分']])}${select('role',t.missing?'6 个代表什么':'5 张代表什么',m.role,[['known-part','已经知道的一部分'],['new-part','后来得到的一部分'],['total','整体']])}</div><div class="x-fields">${n('first','算式第一个数',m.first)}${select('op','运算',m.op,[['plus','＋'],['minus','−']])}${n('second','算式第二个数',m.second)}<span>＝</span>${n('result','算式结果',m.result)}</div>`;
case'x-reason':return `${t.mode==='line'?b('reason-jump','向前走一步'):range('split','从五颗里拿几颗去补十',m.split,0,5)+n('remaining','五颗还剩多少',m.remaining)}${n('total','两种办法得到的总数',m.total)}${t.mode==='repair'?`<div class="x-fields">${select('error','拆分后哪个数该改',m.error,[['five','拆分后的最后一个 5'],['eight','最前面的 8']])}${select('why','错在哪里',m.why,[['twice','拿走 2 后还保留原 5，重复算了'],['sign','加法应该写减法']])}</div>`:''}`;
case'x-regroup':return `<div class="choice-line">${b('join-units','把两组放到一起')}${b('exchange','十个一，换成一个十')}</div>${n('total','合起来多少',m.total)}${t.error?select('reason','为什么不能写 315',m.reason,[['exchange','十五个一先换出一个十，位值才正确'],['join','把数字连起来就好']]):''}`;
case'x-proof':return `<div class="x-fields">${range('a','第一组几对',m.a,1,6)}${range('b','第二组几对',m.b,1,6)}</div>${b('join-pairs','把这两组拼在一起并记录')}<p>按理由的顺序点选，再点可取回：</p><div class="choice-line">${['even','paired','none','join'].map(k=>b('proof-step',proofNames[k],`data-value="${k}" aria-pressed="${m.chain.includes(k)}"`)).join('')}</div><p>搭一个反例，推翻“任何两个数相加都为偶数”：</p><div class="x-fields">${range('counterA','第一个数',m.counterA,0,12)}${range('counterB','第二个数',m.counterB,0,12)}</div>${b('counter-build','把它们两两配对')}${input('why','这个理由为什么适用于没试过的偶数（可选）',m.why)}`;
default:return'';}}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
